import {SqliteAgentActionJournal,AgentActionRecoveryWorker,createActionHttpsVerifier} from '../../dist/index.js';
const [path,url]=process.argv.slice(2),scope={tenantId:'tenant',agentId:'agent'};
const journal=new SqliteAgentActionJournal(path,{scope,runId:'run',leaseToken:'retired-token',clock:()=>110}),errors=[];
try{const verify=createActionHttpsVerifier({scope,runId:'run',operationId:'operation',url,bearerToken:'a'.repeat(32),timeoutMs:5000,maxPending:1,interpret:(body,context)=>{if(!body||body.state!=='applied'||body.key!==context.idempotencyKey||!body.result)throw Error('Unverified provider evidence');return {outcome:'applied',result:body.result};}}),worker=new AgentActionRecoveryWorker({journal,maxPerPass:5,pollMs:100,authorize:()=>true,evidence:()=>({principalId:'operator',reference:'provider-case'}),verify,onError:error=>errors.push(error.message)}),count=await worker.runOnce();await worker.stop();process.send({count,status:journal.get('call').status,errors,evidence:journal.listReconciliations()});}catch(error){process.send({error:String(error)});}finally{journal.close();}
